import React, { useState } from 'react';
import alertManager from './utils/alertManager';

const Judges = ({ 
  judges, 
  judgeInput, 
  setJudgeInput, 
  handleAddJudge, 
  handleDeleteJudge,
  handleEditJudge 
}) => {
  const [pinInput, setPinInput] = useState('');
  const [useAutoPin, setUseAutoPin] = useState(true);
  const [showPin, setShowPin] = useState(false);

  const generatePin = () => {
    return Math.floor(1000 + Math.random() * 9000).toString();
  };

  const handleGeneratePin = () => {
    const newPin = generatePin();
    setPinInput(newPin);
    setUseAutoPin(false);
  };

  const handleAddJudgeWithPin = () => {
    if (!judgeInput.trim()) {
      alertManager.warning('Validation Error', 'Please enter a judge name');
      return;
    }

    if (!useAutoPin && (!pinInput.trim() || pinInput.length !== 4 || !/^\d+$/.test(pinInput))) {
      alertManager.warning('Validation Error', 'Please enter a valid 4-digit PIN');
      return;
    }

    const finalPin = useAutoPin ? null : pinInput.trim();
    handleAddJudge(judgeInput.trim(), finalPin);

    // Reset form
    setJudgeInput('');
    setPinInput('');
    setUseAutoPin(true);
  };
  const handleDeleteClick = (judge) => {
    alertManager.confirm(
      'Delete Judge',
      `Are you sure you want to delete judge "${judge.name}"? This action cannot be undone.`,
      async () => {
        try {
          await handleDeleteJudge(judge.id);
          alertManager.success('Judge Deleted', `Judge "${judge.name}" has been deleted successfully.`);
        } catch (error) {
          alertManager.error('Deletion Failed', `Failed to delete judge: ${error.message}`);
        }
      }
    );
  };

  return (
    <section className="section">
      <h2>Adding Judges</h2>
      <div className="table-container">
        <table className="data-table">
          <thead>
            <tr>
              <th>No.</th>
              <th>Name</th>
              <th>PIN</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {judges.map((judge, index) => (
              <tr key={judge.id}>
                <td>{index + 1}</td>
                <td>{judge.name}</td>
                <td>{judge.pin}</td>
                <td>
                  <button 
                    className="action-btn edit-btn" 
                    title="Edit"
                    onClick={() => handleEditJudge(judge)}
                  >
                    <i className="fi fi-rr-edit"></i>
                  </button>
                  <button 
                    className="action-btn delete-btn" 
                    onClick={() => handleDeleteClick(judge)} 
                    title="Delete"
                  >
                    <i className="fi fi-rr-trash"></i>
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="input-group">
        <div className="judge-input-row">
          <input
            type="text"
            placeholder="Enter judge name"
            value={judgeInput}
            onChange={(e) => setJudgeInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleAddJudgeWithPin()}
          />
        </div>

        <div className="pin-input-row">
          <div className="pin-toggle">
            <label className="toggle-label">
              <input
                type="checkbox"
                checked={useAutoPin}
                onChange={(e) => setUseAutoPin(e.target.checked)}
              />
              <span className="toggle-slider"></span>
              Auto-generate PIN
            </label>
          </div>

          {!useAutoPin && (
            <div className="pin-input-container">
              <input
                type={showPin ? "text" : "password"}
                placeholder="Enter 4-digit PIN"
                value={pinInput}
                onChange={(e) => setPinInput(e.target.value.replace(/\D/g, '').slice(0, 4))}
                maxLength="4"
                onKeyPress={(e) => e.key === 'Enter' && handleAddJudgeWithPin()}
              />
              <button 
                type="button"
                className="show-pin-btn"
                onClick={() => setShowPin(!showPin)}
                title={showPin ? "Hide PIN" : "Show PIN"}
              >
                <i className={showPin ? "fi fi-rr-eye-slash" : "fi fi-rr-eye"}></i>
              </button>
              <button 
                type="button"
                className="generate-pin-btn"
                onClick={handleGeneratePin}
                title="Generate random PIN"
              >
                <i className="fi fi-rr-dice"></i>
              </button>
            </div>
          )}
        </div>

        <button className="submit-btn" onClick={handleAddJudgeWithPin}>
          <i className="fi fi-rr-user-plus"></i>
          Add Judge
        </button>
      </div>
      <div className="notes">
        <p>Note: Arrange the order of judges</p>
        <p>Note: Choose between auto-generated or manual PIN entry</p>
        <p>Note: PIN must be exactly 4 digits</p>
      </div>
    </section>
  );
};

export default Judges;
